SELECT p.code,p.name,MIN(v.price) original_price,MIN(v.price)-COALESCE(MAX(CASE WHEN pm.discount_type='PERCENT' THEN ROUND(v.price*pm.discount_value/100,0) WHEN pm.discount_type='AMOUNT' THEN pm.discount_value ELSE 0 END),0) final_price FROM products p JOIN product_variants v ON v.product_id=p.id LEFT JOIN promotion_details pd ON pd.product_id=p.id LEFT JOIN promotions pm ON pm.id=pd.promotion_id AND pm.status=1 AND GETDATE() BETWEEN pm.start_date AND pm.end_date GROUP BY p.code,p.name ORDER BY p.code;